#!/usr/bin/env python3
"""Reproduce the Udemie Demi mascot v2 ZIP from the validated source generator.

Run from repository root. Output:
  udemie-demi-asset-pack-v2.zip
  demi_v2_assets/{png,svg,previews,README.md}
Requires svgwrite, CairoSVG and Pillow. Asset sources are vector paths.
"""
import base64
import lzma
import ast
from pathlib import Path
payload=""
program=lzma.decompress(base64.b64decode(payload)).decode("utf-8")
# The source was authored in a sandbox; redirect its output to the current working dir.
program=program.replace("/mnt/data", ".")
# Validate syntactically before executing the reproducible source.
ast.parse(program)
exec(compile(program, "<demi-v2-vector-generator>", "exec"), {"__name__":"__main__"})
